"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { colors, typography } from "@ecochef/design-tokens";
import { Download, Printer, FileText, MessageCircle, X } from "lucide-react";
import { createAuthenticatedWebApi } from "../../../src/lib/api";
import { StoreRequired } from "../components/store-required";
import { ThemedSelectControl } from "../components/themed-controls";
import { DownloadOutcome, type DownloadResult } from "../components/download-outcome";
import { buildOrdersCsv, filterOrders, orderMonth, orderStatus, type Order } from "./order-export";
import { OrderChat } from "./order-chat";

const next: Record<string,string>={placed:"preparing",pending:"preparing",preparing:"ready",ready:"completed"};
const statusLabel=orderStatus;
const currentMonth=()=>orderMonth(new Date().toISOString());

export default function Orders() {
  const [orders, setOrders] = useState<Order[]>([]), [filter, setFilter] = useState("All"), [selected, setSelected] = useState<Order>(), [chatOrder, setChatOrder] = useState<Order>();
  const [cancelOrder,setCancelOrder]=useState<Order>();
  const [cancelling,setCancelling]=useState(false);
  const [cancelError,setCancelError]=useState("");
  const [cancellationFeedback,setCancellationFeedback]=useState<{orderId:string;status:"cancellation_pending"|"cancelled"}>();
  const [advancingOrderId,setAdvancingOrderId]=useState<string>();
  const api=useMemo(()=>createAuthenticatedWebApi("/api/ecochef"),[]);
  const [year,setYear]=useState(()=>currentMonth().slice(0,4)),[month,setMonth]=useState(()=>currentMonth().slice(5));
  const [error,setError]=useState(""),[loading,setLoading]=useState(true),[exportOpen,setExportOpen]=useState(false),[exporting,setExporting]=useState(false);
  const [outcome,setOutcome]=useState<DownloadResult>();
  const exportDialog=useRef<HTMLDialogElement>(null),exportPending=useRef(false);
  const load=useCallback(async()=>{const result=await api.getVendorOrders<{orders:Order[]}>();setOrders(result.orders);setError("");return result.orders;},[api]);
  useEffect(()=>{let active=true;const refresh=async()=>{try {const result=await api.getVendorOrders<{orders:Order[]}>();if(active){setOrders(result.orders);setCancellationFeedback(current=>current?.status==="cancellation_pending"&&result.orders.some(order=>order.id===current.orderId&&order.status==="cancelled")?{...current,status:"cancelled"}:current);setError("");}}catch(failure){if(active)setError(failure instanceof Error?failure.message:"Orders could not be loaded.");}finally{if(active)setLoading(false);}};void refresh();const timer=setInterval(()=>void refresh(),5000);return()=>{active=false;clearInterval(timer);};},[api]);
  useEffect(()=>{const open=()=>setExportOpen(true);window.addEventListener("ecochef:export-orders",open);return()=>window.removeEventListener("ecochef:export-orders",open);},[]);
  useEffect(()=>{if(exportOpen && !exportDialog.current?.open)exportDialog.current?.showModal();else if(!exportOpen)exportDialog.current?.close();},[exportOpen]);
  const years=useMemo(()=>{const current=Number(currentMonth().slice(0,4));const earliest=Math.min(current,...orders.map(order=>Number(orderMonth(order.order_date).slice(0,4))));return Array.from({length:current-earliest+1},(_,index)=>({value:String(current-index),label:String(current-index)}));},[orders]);
  const months=[{value:"all",label:"All months"},...Array.from({length:12},(_,index)=>({value:String(index+1).padStart(2,"0"),label:new Date(Date.UTC(2000,index,1)).toLocaleDateString("en-MY",{month:"long",timeZone:"Asia/Kuala_Lumpur"})}))];
  const dated=filterOrders(orders,year,month),visible=filterOrders(orders,year,month,filter);
  const periodLabel=month==="all"?year:`${months.find(option=>option.value===month)?.label} ${year}`;
  const advance = async (order: Order) => { const status = next[order.status]; if (!status || advancingOrderId) return; if (status === "completed" && !window.confirm(order.fulfillment_method === "pickup" ? "Confirm the customer has collected this order? Mark it complete only after handing over every item." : "Confirm this order has been delivered to the customer? Mark it complete only after the handover is confirmed.")) return; setError(""); setAdvancingOrderId(order.id); try { await api.updateVendorOrderStatus(order.id, status); setOrders(current => current.map(item => item.id === order.id ? {...item, status} : item)); try { await load(); } catch { /* The saved status is already shown; the regular refresh will retry. */ } } catch (cause) { setError(cause instanceof Error ? cause.message : "The order could not be updated."); } finally { setAdvancingOrderId(undefined); } };
  const confirmCancellation=async()=>{
    if(!cancelOrder||cancelling)return;
    setCancelling(true);setCancelError("");setCancellationFeedback(undefined);
    try{
      const result=await api.updateVendorOrderStatus<{status:string}>(cancelOrder.id,"cancelled");
      setOrders(current=>current.map(order=>order.id===cancelOrder.id?{...order,status:result.status}:order));
      try { await load(); } catch { /* The saved status is shown; the regular refresh will retry. */ }
      setCancelOrder(undefined);
      if(result.status==="cancelled"||result.status==="cancellation_pending")setCancellationFeedback({orderId:cancelOrder.id,status:result.status});
    }catch(cause){setCancelError(cause instanceof Error?cause.message:"The order could not be cancelled or refunded.");}
    finally{setCancelling(false);}
  };
  const exportCsv=async()=>{
    if(exportPending.current)return;exportPending.current=true;setExporting(true);
    try {const latest=await load();const matching=filterOrders(latest,year,month,filter);download(new Blob([buildOrdersCsv(matching)],{type:"text/csv;charset=utf-8"}),`ecochef-orders-pickup-${year}${month==="all"?"":"-"+month}-${filter.toLowerCase()}.csv`);setExportOpen(false);setOutcome({success:true,downloadName:"CSV",title:"CSV ready",message:`Your ${periodLabel} CSV with ${matching.length.toLocaleString("en-MY")} order${matching.length===1?"":"s"} is ready and the download has started.`});}
    catch(failure){setOutcome({success:false,message:failure instanceof Error?failure.message:"The CSV could not be downloaded. Please try again."});}
    finally{exportPending.current=false;setExporting(false);}
  };
  return <StoreRequired><main className="workspace orders-workspace"><header className="page-head"><div><h1>Order Fulfilment Pipeline</h1><span>{dated.filter((order) => ["placed","pending","preparing","ready"].includes(order.status)).length} Active Orders</span><p>Track paid customer orders, pickup slots, and fulfilment progress.</p></div><button className="secondary" onClick={()=>setExportOpen(true)}><Download size={15} /> Export CSV</button></header>{cancellationFeedback ? <p className={`order-cancellation-feedback ${cancellationFeedback.status === "cancelled" ? "complete" : "pending"}`} role="status">{cancellationFeedback.status === "cancelled" ? `Order #${cancellationFeedback.orderId.slice(0,8).toUpperCase()} cancelled. The refund was issued and its products were returned to stock.` : `Refund processing for order #${cancellationFeedback.orderId.slice(0,8).toUpperCase()}. The order will be cancelled and restocked once Stripe confirms the refund.`}</p> : null}{error ? <p className="product-form-error" role="alert">{error}</p> : null}
    <div className="filterbar order-filterbar"><div>{["All", "Pending", "Preparing", "Ready", "Completed", "Cancelled"].map((value) => <button className={filter === value ? "active" : ""} onClick={() => setFilter(value)} key={value}>{value}</button>)}</div><div className="order-period-controls"><label className="order-period"><span>Year</span><ThemedSelectControl ariaLabel="Order year" value={year} onChange={setYear} options={years}/></label><label className="order-period"><span>Month</span><ThemedSelectControl ariaLabel="Order month" value={month} onChange={setMonth} options={months}/></label></div></div>
    <p className="dashboard-period-note">{periodLabel} · {filter} statuses · Delivery and pickup · Malaysia time</p>
    {loading?<p role="status" className="workspace-note">Loading orders…</p>:null}
    {visible.length ? <div className="data-table orders-table"><div className="tr th"><span>Order ID &amp; Date</span><span>Customer Details</span><span>Items Summary</span><span>Total &amp; Slot</span><span>Pipeline Status</span><span>Fulfilment Action</span><span aria-label="Order tools" /></div>{visible.map((order) => <div className="tr" key={order.id}><span><b>#{order.id.slice(0, 8).toUpperCase()}</b><small>{new Date(order.order_date).toLocaleString("en-MY", { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" })}</small></span><span><b>{order.customer_name}</b><small>{order.phone_number || order.email}</small></span><span>{order.items}</span><span><b>RM{Number(order.total).toFixed(2)}</b><small>{order.fulfillment_method === "pickup" ? "Pickup" : "Delivery"} · {new Date(order.arrival_at).toLocaleString("en-MY", { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" })}</small></span><span><i className={`pill ${order.status}`}>{statusLabel(order.status)}</i>{order.cancellation_reason ? <small>{order.cancellation_reason}</small> : null}</span><span className="order-fulfilment-action">{order.action_supported && next[order.status] ? <button className="table-action" onClick={() => void advance(order)}>{order.status === "ready" ? order.fulfillment_method === "pickup" ? "Confirm Collected" : "Confirm Delivered" : order.status === "preparing" ? "Mark Ready" : "Start Preparing"}</button> : <small>{order.action_supported ? "No action needed" : "Multi-store order"}</small>}</span><span className="order-actions">{order.action_supported && ["placed","pending","cancellation_pending"].includes(order.status) ? <button className="vendor-icon-action cancel-order-icon" aria-label={`${order.status === "cancellation_pending" ? "Check refund for" : "Cancel and refund"} order ${order.id}`} title={order.status === "cancellation_pending" ? "Check refund status" : "Cancel and refund order"} onClick={() => {setCancelError("");setCancelOrder(order);}}><X size={16}/></button> : null}<button className="vendor-icon-action" aria-label={`Message ${order.customer_name}`} title="Message customer" onClick={() => setChatOrder(order)}><MessageCircle size={16} /></button><button className="vendor-icon-action" aria-label={`Open print slip for order ${order.id}`} title="Open order slip" onClick={() => setSelected(order)}><Printer size={16} /></button></span></div>)}</div> : <p className="data-empty panel-empty">No orders match this period and status.</p>}
    <dialog ref={exportDialog} className="modal-card dashboard-export-dialog" aria-labelledby="orders-export-title" onCancel={event=>{if(exporting)event.preventDefault();else setExportOpen(false);}} onClose={()=>{if(!exporting)setExportOpen(false);}}><header><h2 id="orders-export-title"><Download size={20}/> Export CSV</h2><button type="button" aria-label="Close export options" disabled={exporting} onClick={()=>setExportOpen(false)}><X size={20}/></button></header><p>Download delivery and pickup orders for the selected month or whole year.</p><div className="dashboard-report-fields"><label><span>Year</span><ThemedSelectControl ariaLabel="CSV year" disabled={exporting} value={year} onChange={setYear} options={years}/></label><label><span>Month</span><ThemedSelectControl ariaLabel="CSV month" disabled={exporting} value={month} onChange={setMonth} options={months}/></label></div><footer><button type="button" className="secondary" disabled={exporting} onClick={()=>setExportOpen(false)}>Cancel</button><button type="button" className="cta" disabled={exporting||loading} onClick={()=>void exportCsv()}><Download size={16}/>{exporting?"Preparing CSV…":"Download CSV"}</button></footer></dialog>
    {cancelOrder ? <div className="modal-backdrop"><section className="modal-card confirm-card" role="alertdialog" aria-modal="true" aria-labelledby="order-cancel-title"><span><X size={24}/></span><h2 id="order-cancel-title">{cancelOrder.status === "cancellation_pending" ? "Check this refund?" : "Cancel and refund this order?"}</h2><p>{cancelOrder.status === "cancellation_pending" ? `The refund for order #${cancelOrder.id.slice(0,8).toUpperCase()} has started. Check its latest status and finish cancellation when Stripe confirms it.` : `Order #${cancelOrder.id.slice(0,8).toUpperCase()} will be cancelled, RM ${Number(cancelOrder.total).toFixed(2)} will be refunded to the customer’s original payment method, and its products will return to stock.`}</p>{cancelError ? <p role="alert" className="product-form-error">{cancelError}</p> : null}<footer><button type="button" className="neutral-button" disabled={cancelling} onClick={()=>setCancelOrder(undefined)}>Keep order</button><button type="button" className="danger-button" disabled={cancelling} onClick={()=>void confirmCancellation()}>{cancelling ? "Checking…" : cancelOrder.status === "cancellation_pending" ? "Check refund" : "Cancel and refund"}</button></footer></section></div> : null}
    <DownloadOutcome outcome={outcome} close={()=>setOutcome(undefined)}/>
    {chatOrder ? <OrderChat orderId={chatOrder.id} storeId={chatOrder.store_id} customerName={chatOrder.customer_name} close={() => setChatOrder(undefined)} /> : null}{selected ? <OrderDetail order={selected} close={() => setSelected(undefined)} /> : null}</main></StoreRequired>;
}

function OrderDetail({ order, close }: { order: Order; close: () => void }) { return <div className="modal-backdrop"><article className="modal-card order-detail"><header><div><small>ORDER SLIP</small><h2>Order #{order.id.slice(0, 8).toUpperCase()}</h2><span>{new Date(order.order_date).toLocaleString("en-MY")}</span></div><button onClick={close}><X /></button></header><div className="order-slip-grid"><section><h3>Customer</h3><b>{order.customer_name}</b><span>{order.phone_number || order.email}</span><span>{order.delivery_address}</span></section><section><h3>Fulfilment</h3><b>{order.fulfillment_method === "pickup" ? "Store pickup" : "Delivery"}</b><span>{statusLabel(order.status)}</span><span>{new Date(order.arrival_at).toLocaleString("en-MY")}</span></section></div><section className="slip-items"><h3>Ordered items</h3><p>{order.items}</p></section>{order.cancellation_reason ? <p className="slip-cancellation"><b>Cancellation reason:</b> {order.cancellation_reason}</p> : null}<footer><strong><small>Total bill</small>RM {Number(order.total).toFixed(2)}</strong>{order.status === "completed" ? <button className="cta" onClick={() => createOrderPdf(order)}><FileText size={16} /> Generate PDF Slip</button> : <small>PDF slip is available after completion.</small>}</footer></article></div>; }
function download(blob: Blob, name: string) { const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = name; document.body.appendChild(anchor); anchor.click(); anchor.remove(); setTimeout(() => URL.revokeObjectURL(url), 1000); }
function createOrderPdf(order: Order) {
  const clean = (value: unknown) => String(value ?? "").replace(/[^\x20-\x7E]/g, " ").replaceAll("\\", "\\\\").replaceAll("(", "\\(").replaceAll(")", "\\)");
  const rgb = (hex: string) => [1, 3, 5].map((offset) => (parseInt(hex.slice(offset, offset + 2), 16) / 255).toFixed(4)).join(" ");
  const printSize = typography.print.size;
  const text = (value: unknown, x: number, y: number, size: number = printSize.body, colour: string = colors.text) => `${rgb(colour)} rg BT /F1 ${size} Tf ${x} ${y} Td (${clean(value)}) Tj ET`;
  const content = [
    `${rgb(colors.primaryStrong)} rg 0 714 595 128 re f`,
    text("ECOCHEF", 48, 800, printSize.title, colors.surface), text("ORDER FULFILMENT SLIP", 48, 774, printSize.body, colors.primarySoft),
    text(`#${order.id.slice(0, 8).toUpperCase()}`, 420, 798, printSize.secondary, colors.surface), text(new Date(order.order_date).toLocaleString("en-MY"), 330, 775, printSize.caption, colors.primarySoft),
    text("CUSTOMER", 48, 672, printSize.label, colors.primaryStrong), text(order.customer_name, 48, 648, printSize.secondary), text(order.phone_number || order.email, 48, 628, printSize.label, colors.textMuted),
    text("FULFILMENT", 330, 672, printSize.label, colors.primaryStrong), text(order.fulfillment_method === "pickup" ? "Store pickup" : "Delivery", 330, 648, printSize.secondary), text(statusLabel(order.status), 330, 628, printSize.label, colors.textMuted),
    `${rgb(colors.border)} RG 48 590 499 0 re S`, text("ORDERED ITEMS", 48, 566, printSize.label, colors.primaryStrong), text(order.items, 48, 538, printSize.body),
    `${rgb(colors.border)} RG 48 495 499 0 re S`, text("DELIVERY / PICKUP ADDRESS", 48, 468, printSize.label, colors.primaryStrong), text(order.delivery_address, 48, 442, printSize.label),
    `${rgb(colors.primarySoft)} rg 48 348 499 62 re f`, text("TOTAL BILL", 68, 384, printSize.label, colors.primaryStrong), text(`RM ${Number(order.total).toFixed(2)}`, 420, 377, printSize.heading, colors.primaryStrong),
    text("Thank you for choosing EcoChef.", 48, 70, printSize.label, colors.textMuted), text("Reducing food waste, one order at a time.", 48, 52, printSize.caption, colors.textSubtle),
  ].join("\n");
  const objects = ["<< /Type /Catalog /Pages 2 0 R >>", "<< /Type /Pages /Kids [3 0 R] /Count 1 >>", "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>", `<< /Length ${content.length} >>\nstream\n${content}\nendstream`, `<< /Type /Font /Subtype /Type1 /BaseFont /${typography.print.fontFamily} >>`];
  let pdf = "%PDF-1.4\n", offset = pdf.length; const offsets = [0]; objects.forEach((object, index) => { offsets.push(offset); const entry = `${index + 1} 0 obj\n${object}\nendobj\n`; pdf += entry; offset += entry.length; }); const xref = offset; pdf += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n${offsets.slice(1).map((value) => `${String(value).padStart(10, "0")} 00000 n `).join("\n")}\ntrailer << /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`; download(new Blob([pdf], { type: "application/pdf" }), `ecochef-order-${order.id.slice(0, 8)}.pdf`);
}
